const renderer=new T.WebGLRenderer({antialias:true,alpha:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.setClearColor(0xedece4,0);$('viewport').append(renderer.domElement);
const scene=new T.Scene(),camera=new T.PerspectiveCamera(30,1,.1,5000);scene.add(new T.HemisphereLight(0xffffff,0x9b8b76,2.6));const light=new T.DirectionalLight(0xfff8e9,3);light.position.set(-80,120,220);scene.add(light);const fill=new T.DirectionalLight(0xffffff,1);fill.position.set(100,-20,-120);scene.add(fill);const group=new T.Group();scene.add(group);
