fields.forEach(id=>$(id).addEventListener('input',()=>{clearTimeout(timer);$('colorDownload').disabled=$('frameDownload').disabled=$('backDownload').disabled=$('trimDownload').disabled=true;$('status').textContent='Updating your model…';timer=setTimeout(regenerate,350);}));
function download(part){try{const data=Ornament.stl(part==='frame'?current.printFrame:current.back);const url=URL.createObjectURL(new Blob([data],{type:'model/stl'})),a=document.createElement('a');a.href=url;const p=params();a.download=`keepsake-${p.name.replace(/[^a-z0-9]+/gi,'-').replace(/^-|-$/g,'').toLowerCase()||'blank'}-${p.model}-${p.model==='wreath'?'twist-lock-v2':(p.model==='holly'||p.model==='parol'||p.model.startsWith('bauble')||p.model.startsWith('tree'))?'ornament':p.format+'-'+(p.model==='original'?p.decoration:'bow')}-${part}.stl`;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);$('status').textContent=`${part==='frame'?((params().model==='holly'||params().model==='parol'||params().model.startsWith('bauble')||params().model.startsWith('tree'))?'Ornament':'Frame'):'Backing'} STL downloaded. Print at 100% scale in millimetres.`;}catch(e){$('status').textContent='Export failed: '+e.message;}}
$('model').addEventListener('change',()=>{const v=$('model').value;if(['wreath','arch','keepsake','oval'].includes(v)){$('ribbonColor').value=v==='wreath'?'#e9dbbe':'#a83945';$('nameColor').value='#efcc83';}$('landscape').checked=false;color=({original:'#982d36',wreath:'#315a47',arch:'#e7dcc5',keepsake:'#d9b58e',oval:'#e7dcc5',tree:'#315a47',holly:'#b72c3c',parol:'#dfb84e',bauble:'#315a47','bauble-bow':'#b72c3c'})[v];document.querySelectorAll('[data-color]').forEach(b=>b.classList.toggle('selected',b.dataset.color===color));if(v==='arch'){$('format').value='booth2x6';$('photoRows').value='3';}else if(v==='wreath'||v==='oval'){$('format').value='custom';$('width').value='60';$('height').value=v==='wreath'?'60':'80';}else if(v==='keepsake'){$('format').value='mini';}clearTimeout(timer);regenerate();});
for(const id of ['ribbonColor','nameColor'])$(id).addEventListener('input',()=>arrange());
$('trimDownload').onclick=()=>{const svg=Ornament.trimSvg(current);if(!svg)return;const url=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml'})),a=document.createElement('a');a.href=url;a.download='keepsake-'+params().model+'-photo-trim-guide.svg';a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);$('status').textContent='Trim guide downloaded. Print at 100% / actual size.';};
$('colorDownload').onclick=()=>{try{const data=ColorExport.threeMF(current),url=URL.createObjectURL(new Blob([data],{type:'model/3mf'})),a=document.createElement('a');a.href=url;a.download='keepsake-'+params().model+'-color-parts'+(params().model==='wreath'?'-v3':'')+'.3mf';a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);$('status').textContent='3MF downloaded. Import as one object with multiple parts; assign filaments in Objects. '+(current.back?'Backing is a separate STL.':'The ornament is one connected piece.');}catch(e){$('status').textContent='Color export failed: '+e.message;}};
$('frameDownload').onclick=()=>download('frame');$('backDownload').onclick=()=>download('back');
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{mode=b.dataset.view;document.querySelectorAll('[data-view]').forEach(x=>x.classList.toggle('active',x===b));yaw=mode==='back'?Math.PI:0;pitch=mode==='parts'?-.2:0;zoom=1;arrange();});document.querySelectorAll('[data-color]').forEach(b=>b.onclick=()=>{color=b.dataset.color;document.querySelectorAll('[data-color]').forEach(x=>x.classList.toggle('selected',x===b));arrange();});$('reset').onclick=()=>{yaw=mode==='back'?Math.PI:0;pitch=0;zoom=1;arrange();};const canvas=renderer.domElement;canvas.onpointerdown=e=>{drag=true;lastX=e.clientX;lastY=e.clientY;canvas.setPointerCapture(e.pointerId);};canvas.onpointerup=()=>drag=false;canvas.onpointercancel=()=>drag=false;canvas.onpointermove=e=>{if(!drag)return;yaw+=(e.clientX-lastX)*.008;pitch=Math.max(-1.3,Math.min(1.3,pitch+(e.clientY-lastY)*.008));lastX=e.clientX;lastY=e.clientY;arrange();};canvas.addEventListener('wheel',e=>{e.preventDefault();zoom=Math.max(.5,Math.min(2.5,zoom+e.deltaY*.001));arrange();},{passive:false});new ResizeObserver(()=>{const el=$('viewport');renderer.setSize(el.clientWidth,el.clientHeight);camera.aspect=el.clientWidth/el.clientHeight;camera.updateProjectionMatrix();arrange();}).observe($('viewport'));regenerate();

